CREATE TABLE appointment (
  id BIGINT PRIMARY KEY AUTO_INCREMENT, appointment_no VARCHAR(48) NOT NULL, patient_id BIGINT NOT NULL, member_id BIGINT NOT NULL, schedule_id BIGINT NOT NULL, slot_id BIGINT NULL, status VARCHAR(16) NOT NULL, source_client VARCHAR(32) NOT NULL, hold_expires_at DATETIME(3) NULL, booked_at DATETIME(3) NULL, cancelled_at DATETIME(3) NULL, expired_at DATETIME(3) NULL, cancel_reason_code VARCHAR(64) NULL, cancel_reason VARCHAR(512) NULL, idempotency_key VARCHAR(128) NOT NULL, request_fingerprint CHAR(64) NOT NULL, active_booking_key VARCHAR(160) NULL, version INT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3), created_by BIGINT NULL, updated_by BIGINT NULL,
  UNIQUE KEY uk_appointment_no (appointment_no), UNIQUE KEY uk_appointment_patient_idempotency (patient_id,idempotency_key), UNIQUE KEY uk_appointment_active_booking (active_booking_key), KEY idx_appointment_patient_created (patient_id,created_at), KEY idx_appointment_expiration (status,hold_expires_at), KEY idx_appointment_schedule_status (schedule_id,status)
);
CREATE TABLE appointment_status_history (
  id BIGINT PRIMARY KEY AUTO_INCREMENT, appointment_id BIGINT NOT NULL, from_status VARCHAR(16) NULL, to_status VARCHAR(16) NOT NULL, reason_code VARCHAR(64) NULL, reason VARCHAR(512) NULL, operator_type VARCHAR(32) NOT NULL, operator_id BIGINT NULL, trace_id VARCHAR(64) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), KEY idx_appointment_history (appointment_id,created_at)
);
